Here’s the clean **exam-ready** BFS & DFS code in C using an **Adjacency Matrix**. Straightforward. No useless complications.

---

### ✅ BFS and DFS in C (Adjacency Matrix)

```c
#include <stdio.h>
#define MAX 50

int adj[MAX][MAX];
int visited[MAX];
int queue[MAX];
int front = -1, rear = -1;
int n;

// Add element to queue
void enqueue(int v) {
    if(front == -1)
        front = 0;
    rear++;
    queue[rear] = v;
}

// Remove and return element from queue
int dequeue() {
    int v = queue[front];
    front++;
    return v;
}

// Check if queue empty
int isEmpty() {
    return (front == -1 || front > rear);
}

// DFS using Recursion
void DFS(int v) {
    int i;
    visited[v] = 1;
    printf("%d ", v);

    for(i = 0; i < n; i++) {
        if(adj[v][i] == 1 && !visited[i]) {
            DFS(i);
        }
    }
}

// BFS using Queue
void BFS(int start) {
    int i, curr;

    for(i = 0; i < n; i++)
        visited[i] = 0;

    enqueue(start);
    visited[start] = 1;

    while(!isEmpty()) {
        curr = dequeue();
        printf("%d ", curr);

        for(i = 0; i < n; i++) {
            if(adj[curr][i] == 1 && !visited[i]) {
                enqueue(i);
                visited[i] = 1;
            }
        }
    }
}

int main() {
    int i, j, start;

    printf("Enter number of vertices: ");
    scanf("%d", &n);

    printf("Enter adjacency matrix:\n");
    for(i = 0; i < n; i++) {
        for(j = 0; j < n; j++) {
            scanf("%d", &adj[i][j]);
        }
    }

    printf("Enter starting vertex: ");
    scanf("%d", &start);

    printf("\nDFS Traversal: ");
    for(i = 0; i < n; i++)
        visited[i] = 0;
    DFS(start);

    printf("\nBFS Traversal: ");
    BFS(start);

    return 0;
}
```

