## 💻 Code in C (Non-Recursive DFS using Stack + Adjacency Matrix)

```c
#include <stdio.h>
#define MAX 50

int adj[MAX][MAX];
int visited[MAX];
int stack[MAX];
int top = -1;
int n;

void push(int v) {
    stack[++top] = v;
}

int pop() {
    return stack[top--];
}

int isEmpty() {
    return top == -1;
}

void DFS(int start) {
    int i, v, w;

    push(start);
    visited[start] = 1;
    printf("%d ", start);

    while(!isEmpty()) {
        v = stack[top]; // peek

        // find adjacent unvisited
        for(w = 0; w < n; w++) {
            if(adj[v][w] == 1 && !visited[w]) {
                push(w);
                visited[w] = 1;
                printf("%d ", w);
                break;
            }
        }

        // no adjacent found → pop
        if(w == n)
            pop();
    }
}

int main() {
    int i, j, start;

    printf("Enter number of vertices: ");
    scanf("%d", &n);

    printf("Enter adjacency matrix:\n");
    for(i = 0; i < n; i++)
        for(j = 0; j < n; j++)
            scanf("%d", &adj[i][j]);

    printf("Enter start vertex (0 to %d): ", n-1);
    scanf("%d", &start);

    for(i = 0; i < n; i++)
        visited[i] = 0;

    printf("\nDFS Traversal (Non-Recursive): ");
    DFS(start);

    return 0;
}
```

